const cfg = $('Configure').first().json;
const accounts = $('Get connected accounts')
  .all()
  .map((item) => item.json)
  .filter((account) => account.active !== false)
  .map((account) => account.id);

if (accounts.length === 0) {
  throw new Error('No active accounts in this FoPost workspace');
}

// Keep every post under 280 characters so it fits on every network.
return $('New blog post').all().map((article) => {
  const { title, link } = article.json;
  const tail = `\n\n${link}\n${cfg.hashtags}`.trimEnd();
  const room = 280 - title.length - tail.length - 2;
  const summary = (article.json.contentSnippet || '').replace(/\s+/g, ' ').trim();
  const line = summary.length > room ? `${summary.slice(0, Math.max(room - 1, 0))}…` : summary;
  const text = room > 20 && line ? `${title}\n\n${line}${tail}` : `${title}${tail}`;
  return { json: { workspaceId: cfg.workspaceId, accounts, text, title } };
});
